import { useState, useEffect } from 'react';
import {
  JxToggle,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
  JxBadge,
} from '@jinx-ui/react';

interface AppearanceSettings {
  theme: string;
  scale: number;
  compact: boolean;
  font: string;
}

interface AppearanceSettingsScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

const themeLabels: Record<string, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceSettingsScreen({ onChange }: AppearanceSettingsScreenProps) {
  const [theme, setTheme] = useState('system');
  const [scale, setScale] = useState(100);
  const [compact, setCompact] = useState(false);
  const [font, setFont] = useState('sans');

  useEffect(() => {
    onChange?.({ theme, scale, compact, font });
  }, [theme, scale, compact, font, onChange]);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        maxWidth: 480,
        padding: 'var(--jx-r-lg)',
        background: 'var(--jx-surface)',
        borderRadius: 'var(--jx-r-lg)',
        border: '1px solid var(--jx-border)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '20px',
            color: 'var(--jx-text)',
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent">{themeLabels[theme] ?? theme}</JxBadge>
      </div>

      <JxToggle
        items={[
          { value: 'light', label: 'Светлая' },
          { value: 'dark', label: 'Тёмная' },
          { value: 'system', label: 'Системная' },
        ]}
        value={theme}
        onValueChange={setTheme}
      />

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        value={scale}
        onValueChange={setScale}
        unit="%"
        showOutput
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={compact}
        onChange={(event) => setCompact(event.target.checked)}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        options={[
          { value: 'sans', label: 'Inter Tight' },
          { value: 'display', label: 'Fraunces' },
          { value: 'mono', label: 'JetBrains Mono' },
        ]}
        value={font}
        onValueChange={setFont}
      />
    </div>
  );
}

